      [[lang code ='de']]<p> Bei Zugabe von Kaliumpermanganat in Kochsalzlösung entsteht Mangan(IV)-Oxid, Chlorgas und 2 weitere Produkte. 
<br>
Geben Sie die zugehörige Redoxgleichung an.</p>
[[/lang]]
[[lang code='en,other']]
<p>When potassium permanganate is added to a saline solution, manganese(IV)-oxide, chlorine gas, and two other products are formed. 
<br>
Write the corresponding redox equation.
</p>
[[/lang]]

<div style="display: flex; justify-content: center; align-items: center;width:100%;">
<table><tr>
 <td><input id="[[quid id='_fake1'/]]" style="width:100%;"/></td>
 <td><b style="font-size: x-large;">→</b></td>
 <td><input id="[[quid id='_fake2'/]]"  style="width:100%;"/></td>
</tr></table> 
</div>
<div style="display: flex; justify-content: center; align-items: center;">
 [[validation:ans1]]
</div>
<div style="display: flex; justify-content: center; align-items: center;">
[[feedback:prt1]]
</div>
<p>The real input is here, don't touch it as it is not two-way bound. [[input:ans1]]</p>

[[javascript]]
/* We will load the Peggy parser generator to build our own syntax. */
import * as peggy from 'https://cdn.jsdelivr.net/npm/peggy@5.1.0/browser/peggy.min.js';

/* We will also need the JS Maxima parser */
import * as stack_mp from 'https://stack-demo.maths.ed.ac.uk/demo/question/type/stack/corsscripts/cors.php?name=stackmplite.min.js';

/* Hotfix here, if you have STACK 4.12 without commit 0620f88 then the trick to use MPString objects to escape Maxima strings does not work, you may drop this after 4.13 */
stack_mp.MPString.prototype.toString = function() {
   return '"' + this.value.replaceAll("\\", "\\\\").replaceAll('"', "\\\"") + '"';
}; 
/* As this is a JavaScript block we already have stack_js present. */


Promise.all([
 stack_js.request_access_to_input('ans1',true),
 stack_js.request_access_to_input('fake1',true),
 stack_js.request_access_to_input('fake2',true)
]).then(([ans1ref, fake1ref,fake2ref]) => {



/* First lets generate the parser for that custom grammar. */
/* Note that we need to escape things twice here. */
/* Also note the packaging of that source places peggy somewhere we did not expect. */
const chem_parser = window.peggy.generate(`
/* A simple notation for reaction equations. Atoms molecules and charges.
   but no states, their changes or energies.
   
   A simple grammar example. Jut start from the top and try to list 
   the longest imaginable things first.
 */
Expression
  = _ ex:Addition _ { return ex;}
  / _ ex:TermA _ { return ex;}
  
/* Terms that can be added together */
TermA = Multiplied
  / Component
  / Group
  / Electron

/* Addition can have many terms. */
Addition = a:TermA  b:AdditionTail {return [a, ...b].join(' + ');}
AdditionTail = _ '+' _ a:TermA b:AdditionTail {return [a, ...b];}
  / _ '+' _ a:TermA {return [a];}

/* 2O2 etc. */
Multiplied = a:Multiplier _ [*]? _ b:Component {return a + ' * ' + b;}
  / a:Multiplier _ [*]? _ b:Electron {return a + ' * ' + b;}

/* Basic components */
Component = PolyatomicIon
  / Molecule
  / Group
  / Ion
  / Atom

/* We will not check if the element name makes sense at this level. 
Simply assume a capital letter followed by optional lower-case letters is an element.*/
Atom = [A-Z][a-z]* {return 'sc_atom("' + text() + '")';}

Ion = a:Atom '^+' {return 'sc_charge(' + a + ',1)';}
  / a:Atom '^-' {return 'sc_charge(' + a + ',-1)';}
  / a:Atom '^'  b:Integer  '-' {return 'sc_charge(' + a + ',-' + b + ')';}
  / a:Atom '^'  b:Integer  '+' {return 'sc_charge(' + a + ',' + b + ')';}

PolyatomicIon = a:Molecule '^+' {return 'sc_charge(' + a + ',1)';}
  / a:Molecule '^-' {return 'sc_charge(' + a + ',-1)';}
  / a:Molecule '^'  b:Integer  '-' {return 'sc_charge(' + a + ',-' + b + ')';}
  / a:Molecule '^'  b:Integer  '+' {return 'sc_charge(' + a + ',' + b + ')';}
  / a:Group '^+' {return 'sc_charge(' + a + ',1)';}
  / a:Group '^-' {return 'sc_charge(' + a + ',-1)';}
  / a:Group '^'  b:Integer  '-' {return 'sc_charge(' + a + ',-' + b + ')';}
  / a:Group '^'  b:Integer  '+' {return 'sc_charge(' + a + ',' + b + ')';}


/* To complete the charge logic we need electrons, simply map them to a variable. */
Electron = 'e^-' {return ' electron ';}

/* Parenthesis are a bit more important here and we have tow types. */
Group = '(' _ a:Component _ ')' {return 'sc_group(' + a + ')';}
  / '[' _ a:Component _ ']' {return 'sc_groupb(' + a + ')';}

/* O_2 or (XY)_2 etc. Not an ion... */   
Multiple = a:Atom [_]? b:Multiplier {return 'sc_mult(' + a + ',' + b + ')';}
  / a:Group [_]? b:Multiplier {return 'sc_mult(' + a + ',' + b + ')';}

/* O_2 is also a molecule, but does not consist of multiple components. */
Molecule = a:MoleculeComponent b:MoleculeTail {return 'sc_molecule([' + a + ',' + b.join(',') + '])';}
  / Multiple

MoleculeComponent = Multiple
  / Group
  / Atom

MoleculeTail = a:MoleculeComponent b:MoleculeTail {return [a, ...b];}
  / a:MoleculeComponent {return [a];}

Multiplier = Integer
  / '?' {return '?';}

Integer "integer"
  = [0-9]+ { return text(); }

_ "whitespace"
  = [ \\t\\n\\r]*

`);


/* Lets attach that parser to the "fake"-inputs and route the result to the real one. */
const leftside = document.getElementById(fake1ref);
const rightside = document.getElementById(fake2ref);
const real = document.getElementById(ans1ref);
const listener = (e) => {
 /* Either return an `sc_reaction` with both sides populated. 
    Or `sc_err` with the raw inputs and any possible error.
  */
 /* Use the MP-parser classes to escape "strings" correctly */
 let raw = "[" + (new stack_mp.MPString(leftside.value.trim())).toString() + "," + (new stack_mp.MPString(rightside.value.trim())).toString() + "]";

 if (raw === '["",""]') {
  /* The fully empty input case. */
  real.value = '';
  real.dispatchEvent(new Event('change'));
 } else {
  /* Not fully empty, so we will try parsing. */
  let left_err = null;
  let right_err = null;
  let left_parsed = null;
  let right_parsed = null;

  if (leftside.value.trim() !== '') {
   try {
    left_parsed = chem_parser.parse(leftside.value.trim());
   } catch(e) {
    left_err = e.message;
   }
  }
  if (rightside.value.trim() !== '') {
   try {
    right_parsed = chem_parser.parse(rightside.value.trim());
   } catch(e) {
    right_err = e.message;
   }
  }
 
      <text><![CDATA[[[lang code='de']]
<p>Geben Sie die Reaktionsgleichung als Maxima-Ausdruck mit den Chemie-Konstruktoren ein.</p>
<p>Beispiel: <code>sc_reaction(sc_molecule([sc_atom("C"),sc_mult(sc_atom("H"),4)]), sc_molecule([sc_atom("C"),sc_mult(sc_atom("O"),2)]))</code></p>
[[/lang]]
[[lang code='en,other']]
<p>Enter the reaction equation as a Maxima expression using the chemistry constructors.</p>
<p>Example: <code>sc_reaction(sc_molecule([sc_atom("C"),sc_mult(sc_atom("H"),4)]), sc_molecule([sc_atom("C"),sc_mult(sc_atom("O"),2)]))</code></p>
[[/lang]]
<p>[[input:ans1]]</p>
<p>[[validation:ans1]]</p>

  for %_pair in %_a do (
   %_c: assoc(first(%_pair), %_bag, 0),
   %_bag: sublist(%_bag, lambda([%_ex], is(first(%_ex)#first(%_pair)))),
   if is((%_c-second(%_pair))#0) then (
    %_bag: append(%_bag,[[first(%_pair),%_c-second(%_pair)]])
   )
  )
 ),
 return(%_bag)
);

/* 
 * Counts charges of all `sc_charge` and electron` elements in the inputs.
 * If the expression is a `sc_reaction` subtracts the left side from the right side.
 *
 * Set the second argument to 1 to init recursion correctly.
 */
sc_total_charge(ex,mult) := block([%_charge,%_a,%_b,%_pair,%_ex,%_c,simp],
 simp: true,
 %_charge:0,
 if is(ex = electron) then (
  %_charge: -1*mult
 ) else if is(safe_op(ex) = "+") then (
  /* N-ary addition. */
  %_charge: sc_total_charge(args(ex)[1],mult) +  sc_total_charge(apply("+",rest(args(ex))),mult)
 ) else if is(safe_op(ex) = "*") then (
  /* The assumption is that we have no N-ary multiplication present. */
  %_a: args(ex)[1],
  %_b: args(ex)[2],
  if numberp(%_a) then return(sc_total_charge(%_b, mult* %_a)) else
  %_charge:sc_total_charge(%_a,mult*%_b)
 ) else if is(safe_op(ex) = "sc_atom") then %_charge:0
 else if is(safe_op(ex) = "sc_charge") then %_charge: mult*second(ex)
 else if is(safe_op(ex) = "sc_group") then %_charge: sc_total_charge(first(ex),mult)
 else if is(safe_op(ex) = "sc_groupb") then %_charge: sc_total_charge(first(ex),mult)
 else if is(safe_op(ex) = "sc_molecule") then %_charge: sc_total_charge(apply("+",first(ex)),mult)
 else if is(safe_op(ex) = "sc_mult") then %_charge: sc_total_charge(first(ex),mult*second(ex))
 else if is(safe_op(ex) = "sc_reaction") then (
  %_charge: sc_total_charge(second(ex),mult) - sc_total_charge(first(ex),mult)
 ),
 return(%_charge)
);



/* Kaliumpermanganat und Natriumchlorid */
ta1: 
sc_reaction(
    2*sc_molecule( [sc_atom("K"), sc_atom("Mn"), sc_mult(sc_atom("O"),4)   ] )   
    + 6*sc_molecule([sc_atom("Na"), sc_atom("Cl")])
   + 4*sc_molecule([sc_mult(sc_atom("H"),2), sc_atom("O") ]), 
  2*sc_molecule([sc_atom("Mn"), sc_mult(sc_atom("O"),2) ])
+  6*sc_molecule([sc_atom("Na"), sc_atom("O"), sc_atom("H")  ]   )
+  2*sc_molecule([sc_atom("K"), sc_atom("O"), sc_atom("H")  ]   )
+ 3*sc_mult(sc_atom("Cl"), 2 )
);

/* ********** Testfälle ********** */

/* Testfall 1 mit vertauschten Seiten der Reaktionsgleichung */ 
pa1: sc_reaction(second(ta1), first(ta1));

/* Testfall 2: alle stöchiometrischen Koeffizienten skaliert */ 
pa2: sc_reaction(first(ta1)+first(ta1), second(ta1)+second(ta1));

/* Testfall 3: Inkorrekt; eine Seite verdoppelt */ 
pa3: sc_reaction(first(ta1)+first(ta1), second(ta1));


/* Testfall 4: Inkorrekt, 2 Moleküle, aber mit inkorrektem Koeffizientem */
/* NOTE: Wird von molecules_l nicht korrekt verarbeitet! */ 
pa4: sc_reaction(sc_molecule([sc_atom("Na"), sc_atom("Cl")]),  3*sc_molecule([sc_atom("Na"), sc_atom("O"), sc_atom("H")  ]   )
+ 3*sc_mult(sc_atom("B"), 2 ));

/* Erwarteter Score für den Testfall */
scpa4: 1.0*1/7;

/* Testfall 5: Nichts richtig */ 
pa5: sc_reaction( sc_mult( sc_atom("F"),8) , 3*sc_mult(sc_atom("B"), 2 ));


]]>
    
    
      
    
    
      {@ta1@}, <br>
Testfälle `pa1=`{@pa1@}, `pa2=`{@pa2@}, `pa3=`{@pa3@},  `pa4=`{@pa4@},  `pa5=`{@pa5@},
    
    
      [[todo]] 
- molecules_l läuft bei Testfall `pa4` nicht korrekt! Fixen! -> gibt dort die Liste mit dem Molekül aus.
- Andere Schwierigkeiten bei Typ `molecules_l(2*(sc_molecule(..) + sc_molecule))` - wobei Mattis Parser dies ohnehin untersagt einzugeben
- Parser: Rationale Koeffizienten nicht erlauben, also `1/2*O_2` ist ungültig
- Feedback ausgestalten.
- Prüfen und ausgeben, ob die Reaktionsgleichung ausgeglichen ist. (Matti hatte eigentlich eine  Funktion, <code>balance</code>  .... )
- Anderen Reaktionspfeil (beide Richtungen)
- Aufgabenbeschreibung und Dokumentation
[[/todo]]
**Quellen**

- <a href="https://de.chemicalaid.net/tools/equationbalancer.php?equation=KMnO4+%2B+NaCl+%2B+H2O+%3D+MnO2+%2B+NaOH+%2B+KOH+%2B+Cl2"> Link Chemicalaid</a>
- Brieler, Allgemeine Chemie, Übungen S. 10 (Kapitel 4, Aufgabe 3a) - dort allgemeiner Permanganat-Ionen und Chlorid-Ionen in saurer Lösung)
 <a href=https://www.mbzi.de/sites/redoxReaktionen3.php"> Lösung hier </a>

**Aufgabenerzeugung**

- Verschachtelte Moleküle (<code>sc_mult</code> erlaubt nur 2 Argumente. 
  Vielfachheit immer außerhalb von <code>sc_mult</code> bzw. <code>sc_molecule</code>-Umgebungen schreiben
- Notwendig, bei STACK 4.11 die Funktion <code>extract_matching_parts</code> in den Aufgaben-Variablen einzufügen,   da der Parser bzw. die Validierung sonst nicht funktioniert.

**Feedback und PRT**

Verwendet Template, das auf Teilpunkte optimiert ist:

- Es gibt Teilpunkte für jedes korrekte Molekül mit korrekter Vielfachheit auf beiden Seiten der Reaktionsgleichung
- Die Variable <code>weight_wrongcoeff</code> steuert den Faktor, mit dem Moleküle mit falschem Koeffizienten eingehen (default-Wert: 0.5)
- Die Variable <code>malus_wrongmolecule</code> steuert den prozentualen Abzug, den ein falsch angegebenes Molekül gibt (default-Wert: 0)
- Es fehlt noch die Überprüfung, ob die Reaktionsgleichung ausgeglichen ist. Eigentlich hat Matti eine Funktion dafür, nämlich <code>balance</code>

**Mattis Parser**

- In STACK-Version 4.11. fehlt die Funktion <code>extract_matching_parts</code>. Die muss per Hand eingegeben werden in den Fragenvariablen, dann funktioniert es.
- <code>sc_molecule</code> erwartet eine Liste! Die Funktion <code>sc_mult</code>nimmt eine Gruppe/Atom/Molekül und fügt den 2. Eintrag als Subskript an.
    
