        /* Are we in balance? */
balance: sc_elem_counts(ans1,1);
appeared: map(lambda([x],chem_data(first(x), "Name")), sublist(balance, lambda([x],is(second(x)>0))));
disappeared: map(lambda([x],chem_data(first(x), "Name")), sublist(balance, lambda([x],is(second(x)<0))));

charge_balance: sc_total_charge(ans1,1); 

/* Antwort-Überprüfungen und Teilpunkte */

/* Snippets ---- */
molecules_l(eing):= block([dummy, lhs, mult_lhs, molecules_lhs],
dummy: sc_reaction(first(eing) + sc_atom("Dummy"), second(eing) + sc_atom("Dummy")),
lhs: args(first(dummy)),
mult_lhs: [], molecules_lhs: [],
/* if listp(first(lhs)) then return([[first(args(dummy))], [1]]), 
if is(length(lhs) = 1) then return([[first(args(dummy))], [1]]),
if is(length(lhs) = 2) then (if integerp(second(lhs)) then return([[sc_mult(first(lhs), second(lhs)) ], [1]])), */
if integerp(first(lhs)) then return([[second(lhs)], [first(lhs)]]) else 
(for ex in lhs do if integerp(first(args(ex))) then 
(mult_lhs: append(mult_lhs, [first(args(ex))]),  molecules_lhs: append(molecules_lhs, [second(args(ex))]) ) 
else (if is(ex # sc_atom("Dummy")) then (mult_lhs: append(mult_lhs, [1]),   molecules_lhs: append(molecules_lhs, [ex])  )), 
return([molecules_lhs, mult_lhs])));

/* Moleküle mit Vielfachheiten von rechter Seite der Reaktionsgleichung */ 

molecules_r(eing):=block([dummy, lhs, mult_lhs, molecules_lhs],
dummy: sc_reaction(first(eing) + sc_atom("Dummy"), second(eing) + sc_atom("Dummy")),
lhs: args(second(dummy)),
mult_lhs: [], molecules_lhs: [],
/* if listp(first(lhs)) then return([[second(args(dummy))], [1]]),
if is(length(lhs) = 2) then (if integerp(second(lhs)) then return([[sc_mult(first(lhs), second(lhs)) ], [1]])), */
if integerp(first(lhs)) then return([[second(lhs)], [first(lhs)]]) else
(for ex in lhs do  if integerp(first(args(ex))) then 
(mult_lhs: append(mult_lhs, [first(args(ex))]),  molecules_lhs: append(molecules_lhs, [second(args(ex))]) ) 
else (if is(ex # sc_atom("Dummy")) then (mult_lhs: append(mult_lhs, [1]),   molecules_lhs: append(molecules_lhs, [ex])  )), 
return([molecules_lhs, mult_lhs])));

/* Hilfsfunktion, um mehrfach auftretende Moleküle einer Seite zusammenzufassen */
aux_unify_lists(lst1, lst2) := block([aux, aux_lst1, aux_lst2], 
aux_lst1: listify(setify(lst1)), 
aux_lst2: 0*aux_lst1,
for i:1 thru length(aux_lst1) do ( 
    aux: sublist_indices(lst1, lambda([x],x=aux_lst1[i])), 
    for j:1 thru length(aux) do (
        aux_lst2[i]: aux_lst2[i] + lst2[aux[j]]
        )
    ),
return([aux_lst1, aux_lst2]) 
);

ANS_l: aux_unify_lists(molecules_l(ans1)[1], molecules_l(ans1)[2]);
ANS_r: aux_unify_lists(molecules_r(ans1)[1], molecules_r(ans1)[2]);

TA_l: aux_unify_lists(molecules_l(ta1)[1], molecules_l(ta1)[2]);
TA_r: aux_unify_lists(molecules_r(ta1)[1], molecules_r(ta1)[2]);

/* checks if left and right hand side are swapped wrt ta. Does so if one of the opposing sides coincide. */
/* Delete if unwanted */

pred_vertauscht: is(setify(ANS_l[1] ) = setify(TA_r[1] )) or is(setify(ANS_r[1] ) = setify(TA_l[1] ) );
if pred_vertauscht then (ANS_r: ANS_l,  ANS_l: aux_unify_lists(molecules_r(ans1)[1], molecules_r(ans1)[2]) );

/* Test on molecules with correct coefficients */ 

num_molecules: length(TA_l[1]) + length(TA_r[1]);

intersect_l: intersect(setify(ANS_l[1]), setify(TA_l[1])  );
intersect_r:  intersect(setify(ANS_r[1]), setify(TA_r[1])  );
num_intersect: length(intersect_l) + length(intersect_r);

num_malus: length(ANS_l[1]) + length(ANS_r[1]) -   num_intersect;

num_correct_coeff: 0;

/* Aux_l, Aux_r speichert das Verhältnis der stöchiometrischen Koeffizienten desselben Moleküls von ans zu ta */

Aux_l: []; Aux_r:[];
for i:1 thru length(ANS_l[1]) do (aux_indices: sublist_indices(TA_l[1], lambda([x], x=ANS_l[1][i]) ), if is(aux_indices # []) then (Aux_l: append(Aux_l, [ ANS_l[2][i] / TA_l[2][aux_indices[1]]] ), if is(ANS_l[2][i]  =TA_l[2][aux_indices[1]] ) then num_correct_coeff: num_correct_coeff + 1));
for i:1 thru length(ANS_r[1]) do (aux_indices: sublist_indices(TA_r[1], lambda([x], x=ANS_r[1][i]) ), if is(aux_indices # []) then (Aux_r: append(Aux_r, [ ANS_r[2][i] / TA_r[2][aux_indices[1]]] ), if is(ANS_r[2][i]  =TA_r[2][aux_indices[1]] ) then num_correct_coeff: num_correct_coeff + 1));

/* Test der Korrektheit der Lösung */ 

full_correctness: is(num_correct_coeff = num_molecules) and is(num_malus = 0);

/* num_correct ist die Anzahl der richtigen Moleküle, bei denen der Koeffizient falsch ist */
num_correctmol_wrongcoeff: num_intersect - num_correct_coeff; 


/* Steuere Gewichtung bei der Punktzahl von den falsch angegebenen Molekülen und den korrekten Molekülen mit falschem Koeffizienten */ 

malus_wrongmolecule: 0; /* Malus für jedes falsch vorkommende Molekül */ 
weight_wrongcoeff: 0.5;  /* Steuert die Gewichtung von diesen Molekülen in der Mark. Default-Wert: 0.5 */

mark: 1/num_molecules*(  num_correct_coeff +  weight_wrongcoeff*num_correctmol_wrongcoeff - malus_wrongmolecule * num_malus);

/* Teste nun mit aux_l und aux_r, ob die Gleichung nur skaliert bzw. linke oder rechte Seite nur skaliert wurden */


pred_l: is( length(Aux_l) = length(TA_l[2])) and is( length(setify( Aux_l)) = 1 and setify( Aux_l) # {1});
pred_r: is( length(Aux_r) = length(TA_r[2])) and is( length(setify( Aux_r)) = 1 and setify( Aux_r) # {1});
pred: if is(pred_l and pred_r) then is( setify( Aux_l) =setify( Aux_r)) else false;
scale_trigger: pred_l or pred_r;

Feedback_scale: "";
mark_scale:0;


if is(pred_l and pred_r) then (mark_scale:0.8,  Feedback_scale: "Fast richtig, die jeweiligen Seiten der Reaktionsgleichung sind für sich genommen korrekt, passen aber nicht zusammen, die Reaktionsgleichung ist nicht ausgeglichen.");
if is(pred_l and not(pred_r)) then (mark_scale: 0.66, Feedback_scale: "Gut, Sie haben die linke Seite der Reaktionsgleichung korrekt, die rechte Seite ist jedoch falsch.");
if is(pred_r and not(pred_l)) then (mark_scale: 0.66, Feedback_scale: "Gut, Sie haben die rechte Seite der Reaktionsgleichung korrekt, die linke Seite ist jedoch falsch.");
if pred then (mark_scale:1, Feedback_scale:  "Sehr gut! Sie haben eine korrekte Gleichung gefunden.");

/* mark_scale: if pred then 1 else (if is(pred_l and pred_r) then 0.8 else  (if is(pred_l and not(pred_r)) then 0.66 else (if is(pred_r and not(pred_l)) then 0.66)) else 0); */ 
      
      
